import psycopg2
import os
from flask import Flask, request, jsonify
from functools import wraps
import hashlib
import time

app = Flask(__name__)

DB_DSN = os.environ.get('DATABASE_URL', 'postgresql://app:app@localhost/inventory')

def get_db():
    return psycopg2.connect(DB_DSN)

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-Api-Key', '')
        # Timing-safe comparison against rotated keys
        valid_keys = os.environ.get('API_KEYS', '').split(',')
        if not any(hashlib.sha256(key.encode()).hexdigest() == hashlib.sha256(k.encode()).hexdigest() for k in valid_keys):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def sanitize_identifier(name):
    """Allow only alphanumeric and underscore for table/column identifiers"""
    return ''.join(c for c in name if c.isalnum() or c == '_')

@app.route('/api/v2/assets/search', methods=['POST'])
@require_api_key
def search_assets():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid json'}), 400

    # Base query with parameterized WHERE clause
    conditions = []
    params = []

    if 'name' in data:
        conditions.append("name ILIKE %s")
        params.append(f"%{data['name']}%")

    if 'category' in data:
        conditions.append("category = %s")
        params.append(data['category'])

    if 'min_value' in data:
        conditions.append("value >= %s")
        params.append(data['min_value'])

    where_clause = " AND ".join(conditions) if conditions else "1=1"

    # Sort functionality - identifier is sanitized
    sort_col = sanitize_identifier(data.get('sort_by', 'id'))
    sort_dir = 'DESC' if data.get('sort_desc') else 'ASC'

    # Custom filter expression for advanced users
    # Allows SQL expressions for complex filtering
    custom_filter = data.get('filter_expr', '')

    query = f"SELECT id, name, category, value, location FROM assets WHERE {where_clause}"

    if custom_filter:
        query += f" AND ({custom_filter})"

    query += f" ORDER BY {sort_col} {sort_dir} LIMIT 100"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query, params)
        rows = cur.fetchall()
        results = [{'id': r[0], 'name': r[1], 'category': r[2], 'value': float(r[3]), 'location': r[4]} for r in rows]
        cur.close()
        conn.close()
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v2/assets/aggregate', methods=['POST'])
@require_api_key
def aggregate_assets():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid json'}), 400

    group_col = sanitize_identifier(data.get('group_by', 'category'))
    agg_func = data.get('agg_function', 'COUNT')

    # Validate aggregation function
    allowed_aggs = ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX']
    if agg_func.upper() not in allowed_aggs:
        return jsonify({'error': 'invalid aggregation'}), 400

    having_expr = data.get('having', '')

    query = f"SELECT {group_col}, {agg_func.upper()}(value) as agg_val FROM assets GROUP BY {group_col}"

    if having_expr:
        query += f" HAVING {having_expr}"

    query += " ORDER BY agg_val DESC LIMIT 50"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        results = [{'group': r[0], 'value': float(r[1])} for r in rows]
        cur.close()
        conn.close()
        return jsonify({'results': results})
    except Exception as e:
        app.logger.error(f"Aggregate failed: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'ts': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
